/* eslint-disable stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAlign = require( './align/get.js' );
var setAlign = require( './align/set.js' );

var getAspect = require( './aspect/get.js' );
var setAspect = require( './aspect/set.js' );

var getBaseline = require( './baseline/get.js' );
var setBaseline = require( './baseline/set.js' );

var getImage = require( './image/get.js' );
var setImage = require( './image/set.js' );

var getProperties = require( './properties/get.js' );

var getSmooth = require( './smooth/get.js' );
var setSmooth = require( './smooth/set.js' );

var getUrl = require( './url/get.js' );
var setUrl = require( './url/set.js' );


// VARIABLES //

var debug = logger( 'vega:mark:image:encoding-set:main' );


// MAIN //

/**
* Image mark encoding set constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Value} [options.align] - horizontal alignment
* @param {Value} [options.aria] - flag indicating whether to include ARIA attributes in SVG output
* @param {Value} [options.aspect] - flag indicating whether to maintain the aspect ratio
* @param {Value} [options.baseline] - vertical alignment
* @param {Value} [options.blend] - color blend mode
* @param {Value} [options.cursor] - mouse cursor used over a mark
* @param {Value} [options.description] - text description of a mark item for ARIA accessibility
* @param {Value} [options.fill] - fill color
* @param {Value} [options.fillOpacity] - fill opacity
* @param {Value} [options.height] - mark height
* @param {Value} [options.href] - URL to load upon mouse click
* @param {Value} [options.image] - Image or Canvas object
* @param {Value} [options.opacity] - mark opacity
* @param {Value} [options.smooth] - flag indicating whether to apply smoothing when resizing an image
* @param {Value} [options.stroke] - stroke color
* @param {Value} [options.strokeCap] - stroke cap for line ending style
* @param {Value} [options.strokeDash] - stroke dash
* @param {Value} [options.strokeDashOffset] - pixel offset at which to start the dash array
* @param {Value} [options.strokeJoin] - stroke line join method
* @param {Value} [options.strokeMiterLimit] - miter limit at which to bevel a line join
* @param {Value} [options.strokeOpacity] - stroke opacity
* @param {Value} [options.strokeWidth] - stroke width
* @param {Value} [options.tooltip] - tooltip text to show upon mouse hover
* @param {Value} [options.url] - image URL linking to an external site or resource
* @param {Value} [options.width] - mark width
* @param {Value} [options.x] - primary x-coordinate
* @param {Value} [options.x2] - secondary x-coordinate
* @param {Value} [options.xc] - center x-coordinate
* @param {Value} [options.y] - primary y-coordinate
* @param {Value} [options.y2] - secondary y-coordinate
* @param {Value} [options.yc] - center y-coordinate
* @param {Value} [options.zindex] - layering order of sibling mark items
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {ImageEncodingSet} encoding set instance
*
* @example
* var encoding = new ImageEncodingSet();
* // returns <ImageEncodingSet>
*/
function ImageEncodingSet( options ) {
	var nargs;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof ImageEncodingSet ) ) {
		if ( nargs === 0 ) {
			return new ImageEncodingSet();
		}
		return new ImageEncodingSet( options );
	}
	EncodingSet.call( this );
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EncodingSet` prototype.
*/
inherit( ImageEncodingSet, EncodingSet );

/**
* Constructor name.
*
* @private
* @name name
* @memberof ImageEncodingSet
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( ImageEncodingSet, 'name', 'ImageEncodingSet' );

/**
* Encoding specifying the horizontal alignment.
*
* @name align
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'align': new Value({
*         'value': 'center'
*     })
* });
*
* var v = encoding.align;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'align', getAlign, setAlign );

/**
* Encoding specifying a flag indicating whether to maintain the aspect ratio.
*
* @name aspect
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'aspect': new Value({
*         'value': true
*     })
* });
*
* var v = encoding.aspect;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'aspect', getAspect, setAspect );

/**
* Encoding specifying the vertical alignment.
*
* @name baseline
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'baseline': new Value({
*         'value': 'middle'
*     })
* });
*
* var v = encoding.baseline;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'baseline', getBaseline, setBaseline );

/**
* Encoding specifying an Image or Canvas object.
*
* @name image
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'image': new Value({
*         'value': {}
*     })
* });
*
* var v = encoding.image;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'image', getImage, setImage );

/**
* EncodingSet properties.
*
* @name properties
* @memberof ImageEncodingSet.prototype
* @type {Array<string>}
*
* @example
* var encoding = new ImageEncodingSet();
*
* var v = encoding.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( ImageEncodingSet.prototype, 'properties', getProperties );

/**
* Encoding specifying a flag indicating whether to apply smoothing when resizing an image.
*
* @name smooth
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'smooth': new Value({
*         'value': true
*     })
* });
*
* var v = encoding.smooth;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'smooth', getSmooth, setSmooth );

/**
* Encoding specifying an image URL linking to an external site or resource.
*
* @name url
* @memberof ImageEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new ImageEncodingSet({
*     'url': new Value({
*         'value': 'https://example.com/image.png'
*     })
* });
*
* var v = encoding.url;
* // returns <Value>
*/
setReadWriteAccessor( ImageEncodingSet.prototype, 'url', getUrl, setUrl );


// EXPORTS //

module.exports = ImageEncodingSet;
